  async function nextBatchNumber(){const {data}=await client().from('batch_payments').select('batch_number').order('created_at',{ascending:false}).limit(100);let m=0;(data||[]).forEach(x=>{const n=Number(String(x.batch_number||'').replace(/\D/g,''));if(n>m)m=n});return `BATCH-${String(m+1).padStart(4,'0')}`}
  async function saveBatch(){const ids=$('batchExpenseIds').value.split(',').filter(Boolean),exps=ids.map(id=>state.expenses.find(e=>e.id===id)).filter(Boolean);if(!exps.length)return;const total=exps.reduce((s,e)=>s+num(e.outstanding_balance),0),batch_number=await nextBatchNumber();const {data:b,error}=await client().from('batch_payments').insert({batch_number,payment_date:$('batchDate').value||today(),bank_account:$('batchBank').value.trim()||null,reference:$('batchReference').value.trim()||null,notes:$('batchNotes').value.trim()||null,total_amount:Number(total.toFixed(2)),status:'draft'}).select().single();if(error)return toast(error.message);const {error:itemErr}=await client().from('batch_payment_items').insert(exps.map(e=>({batch_payment_id:b.id,expense_id:e.id,amount:Number(num(e.outstanding_balance).toFixed(2))})));if(itemErr)return toast(itemErr.message);$('expenseBatchModal').classList.remove('open');toast('Batch payment created. Mark it paid when the bank payment is completed.');renderBatchHistory()}
  async function renderBatchHistory(){const {data,error}=await client().from('batch_payments').select('*,batch_payment_items(id,expense_id,amount)').order('payment_date',{ascending:false}).limit(50);if(error){console.warn(error);return}$('batchHistoryRows').innerHTML=(data||[]).map(b=>`<tr><td>${esc(b.batch_number)}</td><td>${esc(b.payment_date)}</td><td>${b.batch_payment_items?.length||0}</td><td>${money(b.total_amount)}</td><td>${esc(b.status)}</td><td>${b.status==='draft'?`<button class="primary" data-batch-paid="${b.id}">Mark Batch as Paid</button>`:'Paid'}</td></tr>`).join('')||'<tr><td colspan="6">No batch payments.</td></tr>';$('batchHistoryRows').querySelectorAll('[data-batch-paid]').forEach(btn=>btn.onclick=()=>markBatchPaid(btn.dataset.batchPaid,data.find(b=>b.id===btn.dataset.batchPaid)))}
  async function markBatchPaid(id,b){if(!b||!confirm(`Mark ${b.batch_number} as paid? This will record payments against each selected bill.`))return;const items=b.batch_payment_items||[];for(const item of items){const e=state.expenses.find(x=>x.id===item.expense_id);if(!e)continue;const amount=Math.min(num(item.amount),num(e.outstanding_balance));if(amount>0){const {error}=await client().from('expense_payments').insert({expense_id:e.id,batch_payment_id:id,payment_date:b.payment_date,amount,payment_method:'Batch payment',bank_account:b.bank_account,reference:b.reference,notes:b.notes});if(error)return toast(error.message)}}const {error}=await client().from('batch_payments').update({status:'paid',paid_at:new Date().toISOString(),updated_by:window.SAAS?.state?.user?.id||null}).eq('id',id);if(error)return toast(error.message);await loadExpenses();renderPayments();renderDashboard();toast('Batch marked paid')}

  function renderDashboard(){const now=new Date(),month=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,monthExp=state.expenses.filter(e=>String(e.invoice_date).startsWith(month)&&e.payment_status!=='draft'),unpaid=state.expenses.filter(e=>e.payment_status!=='draft'&&num(e.outstanding_balance)>0),overdue=unpaid.filter(e=>e.due_date&&e.due_date<today()),soon=unpaid.filter(e=>e.due_date&&e.due_date>=today()&&e.due_date<=addDays(today(),7)),unrec=state.expenses.filter(e=>!e.reconciled&&e.payment_status!=='draft');$('expDashMonth').textContent=money(monthExp.reduce((a,e)=>a+num(e.total_amount),0));$('expDashGst').textContent=money(monthExp.reduce((a,e)=>a+num(e.gst_amount),0));$('expDashUnpaid').textContent=money(unpaid.reduce((a,e)=>a+num(e.outstanding_balance),0));$('expDashUnpaidCount').textContent=`${unpaid.length} bill${unpaid.length===1?'':'s'}`;$('expDashOverdue').textContent=money(overdue.reduce((a,e)=>a+num(e.outstanding_balance),0));$('expDashOverdueCount').textContent=`${overdue.length} bill${overdue.length===1?'':'s'}`;$('expDashSoon').textContent=money(soon.reduce((a,e)=>a+num(e.outstanding_balance),0));$('expDashSoonCount').textContent=`${soon.length} bill${soon.length===1?'':'s'}`;$('expDashUnreconciled').textContent=money(unrec.reduce((a,e)=>a+num(e.total_amount),0));$('expDashUnreconciledCount').textContent=`${unrec.length} expense${unrec.length===1?'':'s'}`;$('expenseRecentRows').innerHTML=state.expenses.slice(0,8).map(e=>`<tr><td>${esc(e.invoice_date)}</td><td>${esc(e.supplier_name||'—')}</td><td>${esc(e.expense_number)}</td><td>${money(e.total_amount)}</td><td>${badge(statusOf(e))}</td><td><button class="secondary compact-btn" data-recent-view="${e.id}">View</button></td></tr>`).join('')||'<tr><td colspan="6">No expenses yet.</td></tr>';$('expenseRecentRows').querySelectorAll('[data-recent-view]').forEach(b=>b.onclick=()=>viewExpense(b.dataset.recentView));renderDashboardCharts();runExpenseReport()}
  function renderDashboardCharts(){if(!window.Chart)return;const range=Number($('expenseChartRange')?.value||6),months=[];let d=new Date();d=new Date(d.getFullYear(),d.getMonth()-range+1,1);for(let i=0;i<range;i++){months.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);d.setMonth(d.getMonth()+1)}const vals=months.map(m=>state.expenses.filter(e=>String(e.invoice_date).startsWith(m)&&e.payment_status!=='draft').reduce((a,e)=>a+num(e.total_amount),0));if(state.charts.month)state.charts.month.destroy();state.charts.month=new Chart($('expenseMonthChart'),{type:'bar',data:{labels:months.map(m=>new Date(m+'-01T12:00:00').toLocaleDateString(undefined,{month:'short',year:'2-digit'})),datasets:[{label:'Expenses',data:vals,backgroundColor:business()?.settings?.primaryColor||'#17324d',borderRadius:6}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>money(c.raw)}}},scales:{y:{beginAtZero:true,ticks:{callback:v=>money(v)}}}}});const cats=new Map(state.categories.map(c=>[c.id,c.name])),totals={};state.expenses.filter(e=>e.payment_status!=='draft').forEach(e=>{if(e.is_split)(e.expense_lines||[]).forEach(l=>totals[cats.get(l.category_id)||'Uncategorised']=(totals[cats.get(l.category_id)||'Uncategorised']||0)+num(l.total_amount));else totals[cats.get(e.category_id)||'Uncategorised']=(totals[cats.get(e.category_id)||'Uncategorised']||0)+num(e.total_amount)});const top=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,8);if(state.charts.category)state.charts.category.destroy();state.charts.category=new Chart($('expenseCategoryChart'),{type:'doughnut',data:{labels:top.map(x=>x[0]),datasets:[{data:top.map(x=>x[1])}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'},tooltip:{callbacks:{label:c=>`${c.label}: ${money(c.raw)}`}}}}})}

  function reportDates(){const preset=$('expenseReportRange')?.value||'this_month',now=new Date(),end=today();let start;if(preset==='this_month')start=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-01`;else if(preset==='last_month'){const a=new Date(now.getFullYear(),now.getMonth()-1,1),b=new Date(now.getFullYear(),now.getMonth(),0);start=`${a.getFullYear()}-${String(a.getMonth()+1).padStart(2,'0')}-01`;return{start,end:`${b.getFullYear()}-${String(b.getMonth()+1).padStart(2,'0')}-${String(b.getDate()).padStart(2,'0')}`}}else if(preset==='3')start=addDays(end,-90);else if(preset==='6')start=addDays(end,-183);else if(preset==='12')start=addDays(end,-365);else return{start:$('expenseReportFrom').value,end:$('expenseReportTo').value};return{start,end}}
  function runExpenseReport(){if(!$('expenseReportRange'))return;const {start,end}=reportDates();$('expenseCustomReportDates').hidden=$('expenseReportRange').value!=='custom';const rows=state.expenses.filter(e=>e.payment_status!=='draft'&&(!start||e.invoice_date>=start)&&(!end||e.invoice_date<=end));state.reportRows=rows;const total=rows.reduce((a,e)=>a+num(e.total_amount),0),ex=rows.reduce((a,e)=>a+num(e.ex_gst),0),gst=rows.reduce((a,e)=>a+num(e.gst_amount),0),paid=rows.reduce((a,e)=>a+num(e.amount_paid),0),out=rows.reduce((a,e)=>a+num(e.outstanding_balance),0),over=rows.filter(e=>statusOf(e)==='overdue').reduce((a,e)=>a+num(e.outstanding_balance),0);$('expReportTotal').textContent=money(total);$('expReportEx').textContent=money(ex);$('expReportGst').textContent=money(gst);$('expReportPaid').textContent=money(paid);$('expReportOutstanding').textContent=money(out);$('expReportOverdue').textContent=money(over);const suppliers={};rows.forEach(e=>suppliers[e.supplier_name||'Unknown']=(suppliers[e.supplier_name||'Unknown']||0)+num(e.total_amount));$('expenseSupplierReportRows').innerHTML=Object.entries(suppliers).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${money(v)}</td></tr>`).join('')||'<tr><td colspan="2">No data.</td></tr>';const jobs=new Map(state.jobs.map(j=>[j.id,`${j.costing_number} · ${j.job_description||j.customer_name}`])),jobTotals={};rows.forEach(e=>{if(e.is_split)(e.expense_lines||[]).forEach(l=>{if(l.job_costing_id)jobTotals[jobs.get(l.job_costing_id)||'Job']=(jobTotals[jobs.get(l.job_costing_id)||'Job']||0)+num(l.total_amount)});else if(e.job_costing_id)jobTotals[jobs.get(e.job_costing_id)||'Job']=(jobTotals[jobs.get(e.job_costing_id)||'Job']||0)+num(e.total_amount)});$('expenseJobReportRows').innerHTML=Object.entries(jobTotals).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([n,v])=>`<tr><td>${esc(n)}</td><td>${money(v)}</td></tr>`).join('')||'<tr><td colspan="2">No job-linked expenses.</td></tr>'}
  function exportCsv(){const headers=['Expense #','Date','Supplier','Supplier Reference','Description','Ex GST','GST','Total','Amount Paid','Balance','Payment Status','Reconciled','Currency'],rows=state.reportRows.map(e=>[e.expense_number,e.invoice_date,e.supplier_name||'',e.supplier_reference||'',e.description||'',e.ex_gst,e.gst_amount,e.total_amount,e.amount_paid,e.outstanding_balance,statusOf(e),e.reconciled?'Yes':'No',e.currency]);const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(',')).join('\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`expenses-${today()}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}

  function injectModals(){if($('expenseSupplierModal'))return;document.body.insertAdjacentHTML('beforeend',`
<div class="modal" id="expenseSupplierModal"><div class="modal-box expense-modal-box"><button class="close" data-close-exp-modal="expenseSupplierModal">×</button><h2 id="supplierModalTitle">Add Supplier</h2><input type="hidden" id="supplierModalId"><input type="hidden" id="supplierModalFromExpense"><div class="form-grid compact"><label>Supplier name<input id="supplierName"></label><label>Trading name<input id="supplierTrading"></label><label>Contact person<input id="supplierContact"></label><label>Email<input id="supplierEmail" type="email"></label><label>Phone<input id="supplierPhone" type="tel"></label><label>Mobile<input id="supplierMobile" type="tel"></label><label class="wide">Address<input id="supplierAddress"></label><label>Website<input id="supplierWebsite"></label><label>Business / registration #<input id="supplierRegistration"></label><label>GST / tax number<input id="supplierTax"></label><label>Default expense category<select id="supplierDefaultCategory"></select></label><label>Default GST treatment<select id="supplierDefaultGst"><option value="gst">GST</option><option value="no_gst">No GST</option><option value="zero_rated">Zero Rated</option></select></label><label>Payment terms (days)<input id="supplierTerms" type="number" min="0" step="1"></label><label>Bank account<input id="supplierBank"></label><label>Payment reference<input id="supplierPayRef"></label><label class="wide">Notes<textarea id="supplierNotes" rows="3"></textarea></label></div><div class="actions"><button class="secondary" data-close-exp-modal="expenseSupplierModal">Cancel</button><button class="primary" id="saveExpenseSupplier">Save Supplier</button></div></div></div>
<div class="modal" id="expensePaymentModal"><div class="modal-box small-modal"><button class="close" data-close-exp-modal="expensePaymentModal">×</button><h2>Record Payment</h2><p class="hint" id="paymentBillLabel"></p><input type="hidden" id="paymentExpenseId"><div class="form-grid compact"><label>Payment date<input id="paymentDate" type="date"></label><label>Amount<input id="paymentAmount" type="number" min="0.01" step="0.01" inputmode="decimal"></label><label>Payment method<input id="paymentMethod" placeholder="Bank transfer"></label><label>Bank account<input id="paymentBank"></label><label>Reference<input id="paymentReference"></label><label class="wide">Notes<textarea id="paymentNotes" rows="3"></textarea></label></div><div class="actions"><button class="secondary" data-close-exp-modal="expensePaymentModal">Cancel</button><button class="primary" id="saveExpensePayment">Record Payment</button></div></div></div>
<div class="modal" id="expenseBatchModal"><div class="modal-box small-modal"><button class="close" data-close-exp-modal="expenseBatchModal">×</button><h2>Create Batch Payment</h2><p class="hint" id="batchTotalLabel"></p><input type="hidden" id="batchExpenseIds"><div class="form-grid compact"><label>Payment date<input id="batchDate" type="date"></label><label>Bank account<input id="batchBank"></label><label>Payment reference<input id="batchReference"></label><label class="wide">Notes<textarea id="batchNotes" rows="3"></textarea></label></div><div class="actions"><button class="secondary" data-close-exp-modal="expenseBatchModal">Cancel</button><button class="primary" id="saveExpenseBatch">Create Batch Payment</button></div></div></div>
<div class="modal" id="expenseDetailModal"><div class="modal-box expense-modal-box"><button class="close" data-close-exp-modal="expenseDetailModal">×</button><div id="expenseDetailContent"></div></div></div>
<div class="modal" id="expenseDuplicateModal"><div class="modal-box small-modal"><h2>Possible Duplicate Expense</h2><p>An expense with matching supplier, date/reference and amount already exists.</p><p class="notice" id="expenseDuplicateText"></p><div class="actions"><button class="secondary" id="expenseDuplicateCancel">Cancel</button><button class="secondary" id="expenseDuplicateView">View Existing</button><button class="primary" id="expenseDuplicateSave">Save Anyway</button></div></div></div>`);document.querySelectorAll('[data-close-exp-modal]').forEach(b=>b.onclick=()=>$((b.dataset.closeExpModal)).classList.remove('open'));$('saveExpenseSupplier').onclick=saveSupplier;$('saveExpensePayment').onclick=savePayment;$('saveExpenseBatch').onclick=saveBatch}

  function bind(){if(state.init)return;state.init=true;injectModals();document.querySelectorAll('[data-exp-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.expTab));document.querySelectorAll('[data-exp-add]').forEach(b=>b.onclick=newExpense);$('expSupplier').onchange=supplierChanged;$('expCreateSupplier').onclick=()=>openSupplierModal(null,true);$('expCreateCategory').onclick=()=>addCategory(true);$('expSplitToggle').onclick=toggleSplit;$('expAddSplit').onclick=()=>{state.splitLines.push({description:'',category_id:'',job_costing_id:'',amount:0,gst_treatment:$('expGstTreatment').value||'gst',gst_rate:gstRate()});renderSplitLines()};['expAmount','expAmountType','expGstTreatment','expGstAmount'].forEach(id=>$(id).addEventListener('input',updateAmountDisplay));$('expGstOverride').onchange=()=>{$('expGstAmount').readOnly=!$('expGstOverride').checked;updateAmountDisplay()};$('expInvoiceDate').onchange=()=>{const s=state.suppliers.find(x=>x.id===$('expSupplier').value);if(s?.payment_terms_days)$('expDueDate').value=addDays($('expInvoiceDate').value,s.payment_terms_days)};$('expSave').onclick=saveExpense;$('expCancel').onclick=()=>switchTab('bills');$('expTakePhoto').onclick=()=>$('expCameraFile').click();$('expChoosePhoto').onclick=()=>$('expPhotoFile').click();$('expUploadDoc').onclick=()=>$('expDocumentFile').click();$('expNoAttachment').onclick=()=>toast('You can enter and save the expense without an attachment.');['expCameraFile','expPhotoFile','expDocumentFile'].forEach(id=>$(id).onchange=e=>{pickFiles(e.target.files);e.target.value=''});['expenseSearch','expenseSupplierFilter','expenseCategoryFilter','expensePaymentFilter','expenseReconcileFilter','expenseFrom','expenseTo','expenseSort'].forEach(id=>$(id).addEventListener(id==='expenseSearch'?'input':'change',renderBills));document.querySelectorAll('[data-exp-quick]').forEach(b=>b.onclick=()=>{const v=b.dataset.expQuick;if(v==='reconciled'||v==='unreconciled'){$('expensePaymentFilter').value='';$('expenseReconcileFilter').value=v}else{$('expenseReconcileFilter').value='';$('expensePaymentFilter').value=v==='all'?'':v}document.querySelectorAll('[data-exp-quick]').forEach(x=>x.classList.toggle('active',x===b));renderBills()});$('expenseResetFilters').onclick=()=>{['expenseSearch','expenseSupplierFilter','expenseCategoryFilter','expensePaymentFilter','expenseReconcileFilter','expenseFrom','expenseTo'].forEach(id=>$(id).value='');$('expenseSort').value='newest';document.querySelectorAll('[data-exp-quick]').forEach((x,i)=>x.classList.toggle('active',i===0));renderBills()};$('supplierSearch').oninput=renderSuppliers;$('addSupplierBtn').onclick=()=>openSupplierModal();$('addExpenseCategory').onclick=()=>addCategory(false);$('createBatchPayment').onclick=openBatch;$('expenseChartRange').onchange=renderDashboardCharts;$('expenseReportRange').onchange=runExpenseReport;$('expenseReportFrom').onchange=runExpenseReport;$('expenseReportTo').onchange=runExpenseReport;$('expenseExportCsv').onclick=exportCsv;}

  async function init(){bind();await loadReferenceData();await loadExpenses();renderDashboard()}
  window.Expenses={init,onShow,switchTab,refresh:async()=>{await loadReferenceData();await loadExpenses();switchTab(state.activeTab)}};
